  1	'use client';
  2	
  3	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
  4	import { AppShell } from '@/components/AppShell';
  5	import { Button } from '@/components/ui/button';
  6	import { StatusBadge } from '@/components/StatusBadge';
  7	import { Textarea } from '@/components/ui/field';
  8	import { useAuth } from '@/lib/auth';
  9	import { apiFetch } from '@/lib/api';
 10	import { useState } from 'react';
 11	
 12	type Task = {
 13	  id: string;
 14	  publicId: string;
 15	  title: string;
 16	  status: string;
 17	  priority: string;
 18	  address: string;
 19	};
 20	
 21	/** Which evidence kinds this worker has already attached per task. */
 22	type UploadsByTask = Record<string, string[]>;
 23	
 24	function addKind(uploads: UploadsByTask, id: string, kind: string): UploadsByTask {
 25	  const existing = uploads[id] ?? [];
 26	  return existing.includes(kind) ? uploads : { ...uploads, [id]: [...existing, kind] };
 27	}
 28	
 29	export default function WorkerDashboard() {
 30	  const { token } = useAuth();
 31	  const qc = useQueryClient();
 32	  const [notes, setNotes] = useState<Record<string, string>>({});
 33	  const [uploads, setUploads] = useState<UploadsByTask>({});
 34	
 35	  const { data } = useQuery({
 36	    queryKey: ['worker-tasks'],
 37	    enabled: Boolean(token),
 38	    queryFn: () =>
 39	      apiFetch<{ items: Task[] }>('/api/complaints', { token: token! }),
 40	  });
 41	
 42	  const act = useMutation({
 43	    mutationFn: (input: { id: string; status: string; note?: string }) =>
 44	      apiFetch(`/api/complaints/${input.id}/status`, {
 45	        method: 'POST',
 46	        token: token!,
 47	        body: JSON.stringify({ status: input.status, note: input.note }),
 48	      }),
 49	    onSuccess: () => qc.invalidateQueries({ queryKey: ['worker-tasks'] }),
 50	  });
 51	
 52	  const upload = useMutation({
 53	    mutationFn: async (input: { id: string; file: File; kind: string }) => {
 54	      const form = new FormData();
 55	      form.append('file', input.file);
 56	      form.append('kind', input.kind);
 57	      return apiFetch(`/api/complaints/${input.id}/media`, { method: 'POST', token: token!, body: form });
 58	    },
 59	    onSuccess: (_data, input) => setUploads((prev) => addKind(prev, input.id, input.kind)),
 60	  });
 61	
 62	  return (
 63	    <AppShell>
 64	      <h1 className="font-display text-3xl font-semibold">My tasks</h1>
 65	      <p className="text-sm text-slate-600">Only complaints assigned to your field team are listed.</p>
 66	      <ul className="mt-4 space-y-4">
 67	        {data?.items.map((c) => {
 68	          const note = notes[c.id] ?? '';
 69	          const hasAfter = (uploads[c.id] ?? []).includes('AFTER');
 70	          const status = c.status;
 71	
 72	          return (
 73	            <li key={c.id} className="rounded-xl border border-slate-200 bg-white p-4">
 74	              <div className="flex justify-between">
 75	                <p className="font-semibold">
 76	                  {c.publicId} · {c.title}
 77	                </p>
 78	                <div className="flex gap-2">
 79	                  <StatusBadge value={c.priority} />
 80	                  <StatusBadge value={c.status} />
 81	                </div>
 82	              </div>
 83	              <p className="text-sm text-slate-600">{c.address}</p>
 84	
 85	              <Textarea
 86	                className="mt-3"
 87	                value={note}
 88	                onChange={(e) => setNotes((prev) => ({ ...prev, [c.id]: e.target.value }))}
 89	                placeholder="Update notes"
 90	              />
 91	
 92	              <div className="mt-3 flex flex-wrap gap-2">
 93	                {status === 'ASSIGNED' && (
 94	                  <>
 95	                    <Button onClick={() => act.mutate({ id: c.id, status: 'ACCEPTED', note })}>
 96	                      Accept
 97	                    </Button>
 98	                    <Button
 99	                      variant="secondary"
100	                      onClick={() => act.mutate({ id: c.id, status: 'UNDER_REVIEW', note })}
101	                    >
102	                      Decline
103	                    </Button>
104	                  </>
105	                )}
106	                {status === 'ACCEPTED' && (
107	                  <Button onClick={() => act.mutate({ id: c.id, status: 'IN_PROGRESS', note })}>
108	                    Start work
109	                  </Button>
110	                )}
111	                {status === 'ON_HOLD' && (
112	                  <Button onClick={() => act.mutate({ id: c.id, status: 'IN_PROGRESS', note })}>
113	                    Resume
114	                  </Button>
115	                )}
116	                {status === 'IN_PROGRESS' && (
117	                  <Button
118	                    disabled={!hasAfter}
119	                    onClick={() => act.mutate({ id: c.id, status: 'RESOLVED', note })}
120	                  >
121	                    Mark complete
122	                  </Button>
123	                )}
124	
125	                <label className="rounded-lg border px-3 py-2 text-sm">
126	                  Before photo
127	                  <input
128	                    className="hidden"
129	                    type="file"
130	                    accept="image/*"
131	                    onChange={(e) => {
132	                      const file = e.target.files?.[0];
133	                      if (file) upload.mutate({ id: c.id, file, kind: 'BEFORE' });
134	                    }}
135	                  />
136	                </label>
137	                <label className="rounded-lg border px-3 py-2 text-sm">
138	                  After photo
139	                  <input
140	                    className="hidden"
141	                    type="file"
142	                    accept="image/*"
143	                    onChange={(e) => {
144	                      const file = e.target.files?.[0];
145	                      if (file) upload.mutate({ id: c.id, file, kind: 'AFTER' });
146	                    }}
147	                  />
148	                </label>
149	              </div>
150	
151	              {status === 'IN_PROGRESS' && !hasAfter && (
152	                <p className="mt-2 text-xs text-slate-500">
153	                  Upload an after photo to mark this task complete.
154	                </p>
155	              )}
156	            </li>
157	          );
158	        })}
159	      </ul>
160	    </AppShell>
161	  );
162	}

